// Internal encoding structures
// ADCLB: Add with carry long (bottom)
// Encoding: adclb_z_zzz_
// Template: ADCLB  <Zda>.<T>, <Zn>.<T>, <Zm>.<T>
struct AdclbZZzz {
    uint32_t Zda : 5;
    uint32_t Zn : 5;
    uint32_t T : 1;  // fixed: 0b0 (0x0)
    uint32_t _unnamed_6 : 3;  // fixed: 0b010 (0x2)
    uint32_t _unnamed_5 : 2;  // fixed: 0b11 (0x3)
    uint32_t Zm : 5;
    uint32_t _unnamed_4 : 1;  // fixed: 0b0 (0x0)
    uint32_t sz : 1;
    uint32_t _unnamed_3 : 1;  // fixed: 0b0 (0x0)
    uint32_t _unnamed_2 : 1;  // fixed: 0b1 (0x1)
    uint32_t _unnamed_1 : 4;  // fixed: 0b0010 (0x2)
    uint32_t _unnamed_0 : 3;  // fixed: 0b010 (0x2)
};


